contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Try a Deposit and assert that if it does not revert then both the contract's
    // recorded balance for this contract and the contract's Ether balance increased by the amount sent.
    function run(uint depositAmount, uint minSum, address logAddr) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        // ensure this test contract has funds to send for the deposit
        require(address(this).balance >= depositAmount);

        // initialize c so Deposit can be used normally
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.SetLogFile(logAddr); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        // read balances before
        uint beforeRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBal = address(c).balance;

        // attempt Deposit and capture revert
        bool reverted;
        c.Deposit{value: depositAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read balances after
        uint afterRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBal = address(c).balance;

        // General rule: if Deposit did not revert then the recorded balance for this caller
        // increased by exactly depositAmount and the contract's Ether balance increased by exactly depositAmount.
        assert(reverted || (afterRecorded >= beforeRecorded && afterContractBal >= beforeContractBal && (afterRecorded - beforeRecorded) == depositAmount && (afterContractBal - beforeContractBal) == depositAmount));
    }

    // allow this test contract to receive Ether so it can fund deposits
    receive() external payable {}
}

