// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 depositAmount, uint256 minSum, address logAddr) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.SetLogFile(logAddr) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 beforeRecorded;
        try c.balances(address(this)) returns (uint256 __r) { beforeRecorded = __r; } catch { return; }
        uint beforeContractBal = address(c).balance;
        bool reverted;
        try c.Deposit{value: depositAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterRecorded;
        try c.balances(address(this)) returns (uint256 __r) { afterRecorded = __r; } catch { return; }
        uint afterContractBal = address(c).balance;
        assertTrue(reverted || (afterRecorded >= beforeRecorded && afterContractBal >= beforeContractBal && (afterRecorded - beforeRecorded) == depositAmount && (afterContractBal - beforeContractBal) == depositAmount));
    }

    function testFuzz_run(uint256 depositAmount, uint256 minSum, address logAddr) public {
        vm.assume(logAddr.code.length == 0 && uint160(logAddr) > 0xffff && logAddr != address(this) && logAddr != address(c) && logAddr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && logAddr != 0x000000000000000000636F6e736F6c652e6c6f67 && logAddr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && logAddr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(depositAmount, minSum, logAddr);
    }

    receive() external payable {}
}
